#!/usr/bin/env python3
# patch_new_settings_image.py - replace the old Smart Match / translation screenshot in the
# "Randly vs Ome.tv" article (all languages) with the new design.
# Usage (from the project folder omegle-clone):  python patch_new_settings_image.py          (dry run)
#                                               python patch_new_settings_image.py --apply
import os, re, sys, glob, base64
APPLY = '--apply' in sys.argv
PUB = 'public' if os.path.isdir('public') else '.'
NEW = 'randly-country-translation-v2.webp'
OLD = 'randly-country-translation.webp'
W, H = 1200, 649
IMG = ""
p = os.path.join(PUB, NEW)
blob = base64.b64decode(IMG)
if os.path.exists(p) and open(p, 'rb').read() == blob:
    print('SAME   ', NEW)
else:
    print('WRITE  ' if APPLY else 'WOULD WRITE', NEW)
    if APPLY: open(p, 'wb').write(blob)
pat = re.compile(r'(<img src="/?)' + re.escape(OLD) + r'("[^>]*?) width="1000" height="1016"')
changed = same = missing = 0
for f in sorted(glob.glob(os.path.join(PUB, 'post-randly-vs-ome-tv*.html'))):
    s = open(f, 'rb').read().decode('utf-8')
    new, n = pat.subn(lambda m: m.group(1) + NEW + m.group(2) + ' width="%d" height="%d"' % (W, H), s)
    if n == 1:
        print('CHANGE ' if APPLY else 'WOULD CHANGE', os.path.basename(f)); changed += 1
        if APPLY: open(f, 'wb').write(new.encode('utf-8'))
    elif NEW in s:
        same += 1
    else:
        print('NOTE   ', os.path.basename(f), '- old image tag not found (n=%d)' % n); missing += 1
print('changed:', changed, '| already new:', same, '| not found:', missing)
if not APPLY: print('Dry run only. Add --apply to write.')
